<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$statement = $pdo->prepare('SELECT syllabus.id, syllabus.module_title, syllabus.module_order, syllabus.status, courses.title AS course_title FROM syllabus INNER JOIN courses ON courses.id = syllabus.course_id ORDER BY courses.title, syllabus.module_order, syllabus.id'); $statement->execute(); $modules = $statement->fetchAll(); admin_header('Syllabus', 'syllabus/index.php');
?><div class="d-flex justify-content-end mb-3"><a href="create.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Add Module</a></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Course</th><th>Order</th><th>Module</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($modules as $module):?><tr><td><?=e($module['course_title'])?></td><td><span class="badge badge-soft">#<?=e($module['module_order'])?></span></td><td><?=e($module['module_title'])?></td><td><span class="badge text-bg-<?=$module['status']?'success':'secondary'?>"><?=$module['status']?'Active':'Inactive'?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?=e($module['id'])?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?=e($module['id'])?>">Delete</a></td></tr><?php endforeach;?><?php if(!$modules):?><tr><td colspan="5" class="text-center text-secondary py-5">No syllabus modules found.</td></tr><?php endif;?></tbody></table></div></div><?php admin_footer();?>
